{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "نار، وبرد، وسيوف طائرة، ومياه كثيرة، لكي تمتلئ جميع السهول، وتفيض جميع الأنهار بغزارة تلك المياه.",
      "chapter": 15,
      "verse": 41
    },
    {
      "text_ar": "سيهدمون المدن والأسوار، والجبال والتلال، وأشجار الوعر، وعشب المروج، وحبوبها.",
      "chapter": 15,
      "verse": 42
    },
    {
      "text_ar": "سيتقدمون بثبات نحو بابل ويهلكونها.",
      "chapter": 15,
      "verse": 43
    },
    {
      "text_ar": "سيأتون إليها ويحيطون بها. ويسكبون العاصفة وكل الغضب عليها. وحينئذ يصعد الغبار والدخان إلى السماء، وكل الذين حولها ينوحون عليها.",
      "chapter": 15,
      "verse": 44
    },
    {
      "text_ar": "والباقون سيخدمون الذين دمروها.",
      "chapter": 15,
      "verse": 45
    },
    {
      "text_ar": "أيتها الآسيا، يا من تشاركين في جمال بابل، وفي مجد شخصها—",
      "chapter": 15,
      "verse": 46
    },
    {
      "text_ar": "ويل لك أيها البائسة، لأنك جعلت نفسَك مثلها. لقد زينت بناتك للزنا، لكي يرضين ويفتخرن بمحبيك، الذين اشتهوك دائماً!",
      "chapter": 15,
      "verse": 47
    },
    {
      "text_ar": "لقد اتبعتِ التي هي مكروهة في كل أعمالها واختراعاتها. لذلك يقول الله:",
      "chapter": 15,
      "verse": 48
    },
    {
      "text_ar": "\"سأرسل عليك شروراً: ترمل، وفقراً، وجوعاً، وسيفاً، ووبأً، لتخريب بيوتك وتسليمك إلى الدمار والموت.",
      "chapter": 15,
      "verse": 49
    },
    {
      "text_ar": "مجد قوتك سيجف كزهرة عندما يرتفع الحر المرسل عليك.",
      "chapter": 15,
      "verse": 50
    },
    {
      "text_ar": "ستضعفين كامرأة مسكينة مضروبة ومجروحة، بحيث لا تقدرين أن تقبلي أقوياءك ومحبيك.",
      "chapter": 15,
      "verse": 51
    },
    {
      "text_ar": "أكنتُ أتعامل معك بمثل هذه الغيرة\"، يقول الرب،",
      "chapter": 15,
      "verse": 52
    },
    {
      "text_ar": "\"لو لم تقتلي دائماً مختاري، متكبرة ومصفقة بيديك، ومتكلمة عن موتاهم وأنت سكرى؟",
      "chapter": 15,
      "verse": 53
    },
    {
      "text_ar": "\"زيني وجهك!",
      "chapter": 15,
      "verse": 54
    },
    {
      "text_ar": "أجرة الزانية ستكون في حضنك، فلذلك ستجازين.",
      "chapter": 15,
      "verse": 55
    },
    {
      "text_ar": "وكما ستفعلين بمختاري\"، يقول الرب، \"هكذا سيفعل الله بك، ويسلمك إلى أعدائك.",
      "chapter": 15,
      "verse": 56
    },
    {
      "text_ar": "أولادك سيحوتون من الجوع. وستسقطين بالسيف. ومدنك ستتهدم، وكل شعبك في الحقل يهلك بالسيف.",
      "chapter": 15,
      "verse": 57
    },
    {
      "text_ar": "والذين هم في الجبال سيموتون جوعاً، ويأكلون لحم أنفسهم، ويشربون دم أنفسهم، بسبب الجوع إلى الخبز والعطش إلى الماء.",
      "chapter": 15,
      "verse": 58
    },
    {
      "text_ar": "أنت، التعيسة أكثر من الجميع، ستأتي وتقبلي الشرور من جديد.",
      "chapter": 15,
      "verse": 59
    },
    {
      "text_ar": "في العبور، سيقحمون على المدينة المكروهة ويهلكون جزءاً من أرضك، ويشوهون جزءاً من مجدك، ويسجعون مرة أخرى إلى بابل التي دُمرت.",
      "chapter": 15,
      "verse": 60
    }
  ]
}
